import sys
import re
import math
from collections import defaultdict

def evaluate_expression(expr, variables):
    try:
        # Replace variables with their values
        for name, value in variables.items():
            expr = expr.replace(name, str(value))

        # Evaluate the expression safely
        try:
            result = eval(expr, {'__builtins__': None}, {'__import__': None})
        except:
            raise ValueError(f"Error evaluating expression: {expr}")

        return result
    except Exception as e:
        raise ValueError(f"Error: {e}")

def parse_context_file(path):
    variables = {}
    if path and path != '-':
        try:
            with open(path, 'r', encoding='utf-8') as f:
                for line in f:
                    line = line.strip()
                    if not line:
                        continue
                    if '=' in line:
                        name, expr = line.split('=', 1)
                        name = name.strip()
                        expr = expr.strip()
                        try:
                            value = evaluate_expression(expr, variables)
                            variables[name] = value
                        except ValueError as e:
                            print(f"error: {expr}", file=sys.stderr)
                            sys.exit(1)
        except IOError:
            pass
    return variables

def render_template(template_path, context_path):
    variables = parse_context_file(context_path)
    template_lines = []
    try:
        with open(template_path, 'r', encoding='utf-8') as f:
            template_lines = f.readlines()
    except IOError:
        print(f"error: {template_path}", file=sys.stderr)
        sys.exit(1)

    output = []
    for line in template_lines:
        line = line.strip()
        if not line:
            output.append('\n')
            continue

        # Find all regions
        regions = re.findall(r'\{\{([^}]*)\}\}', line)
        if not regions:
            output.append(line)
            continue

        # Process each region
        for i, region in enumerate(regions):
            trimmed = region.strip()
            if '=' in trimmed:
                name, expr = trimmed.split('=', 1)
                name = name.strip()
                if not re.fullmatch(r'[A-Za-z_][A-Za-z0-9_]*', name):
                    raise ValueError(f"Invalid name: {name}")
                try:
                    value = evaluate_expression(expr, variables)
                    variables[name] = value
                    line = line.replace(f'{{{{{region}}}}}', '')
                except ValueError as e:
                    print(f"error: {trimmed}", file=sys.stderr)
                    sys.exit(1)
            else:
                try:
                    value = evaluate_expression(trimmed, variables)
                    line = line.replace(f'{{{{{region}}}}}', str(value))
                except ValueError as e:
                    print(f"error: {trimmed}", file=sys.stderr)
                    sys.exit(1)

        output.append(line)

    # Write the rendered output
    print(''.join(output), end='')

    # Save variables to context file
    try:
        with open(context_path, 'w', encoding='utf-8') as f:
            for name, value in sorted(variables.items()):
                if isinstance(value, int):
                    f.write(f"{name} = {value}\n")
                else:
                    f.write(f"{name} = {value:.1f}\n")
    except IOError:
        pass

if __name__ == "__main__":
    if len(sys.argv) != 3:
        print("Usage: python render.py TEMPLATE_PATH CONTEXT_PATH", file=sys.stderr)
        sys.exit(1)

    template_path = sys.argv[1]
    context_path = sys.argv[2]
    render_template(template_path, context_path)

