    # Load context variables if context_path exists
    if os.path.exists(context_path):
        with open(context_path, 'r', encoding='utf-8') as f:
            for line in f:
                line = line.strip()
                if line and '=' in line:
                    name, value = line.split('=', 1)
                    try:
                        num_value = float(value)
                        if num_value.is_integer():
                            variables[name.strip()] = int(num_value)
                        else:
                            variables[name.strip()] = num_value
                    except ValueError:
                        variables[name.strip()] = value.strip()

